import { balanceDue } from './payments.js';
import { daysBetween, isValidDate } from './dates.js';
import { lineTotal, lineDiscount, lineVat } from './invoices.js';
import { fail, ok } from './result.js';

/**
 * Get invoices that are overdue as of a given date.
 * @param {Array} invoices - Array of all invoices
 * @param {string} asOf - Date in YYYY-MM-DD format
 * @returns {{ ok: true, value: Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }> } | { ok: false, error: string }}
 */
export function overdueInvoices(invoices, asOf) {
  if (!isValidDate(asOf)) return fail('DATE_INVALID');

  const overdue = (invoices ?? [])
    .filter(
      (inv) =>
        (inv.status === 'issued' || inv.status === 'partially_paid') &&
        inv.dueDate &&
        inv.dueDate < asOf
    )
    .map((inv) => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  return { ok: true, value: overdue };
}

/**
 * Generate a summary of VAT by rate.
 * @param {Array} invoices - Array of invoices
 * @returns {{ ok: true, value: Array<{ rate: number, base: number, vat: number }> }}
 */
export function vatSummary(invoices) {
  const vatMap = {};

  (invoices ?? [])
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid' || inv.status === 'paid')
    .forEach((inv) => {
      inv.lines.forEach((line) => {
        const rate = line.vatRate;
        const base = lineTotal(line) - lineDiscount(line);
        const vat = lineVat(line);

        if (!vatMap[rate]) {
          vatMap[rate] = { rate, base: 0, vat: 0 };
        }
        vatMap[rate].base += base;
        vatMap[rate].vat += vat;
      });
    });

  const summary = Object.values(vatMap).sort((a, b) => b.rate - a.rate);

  return ok(summary);
}

