test('lateFee with NET30 payment terms', () => {
  const inv = createAndIssueInvoice('C-001', '2026-10-07', [{ sku: 'WORKSHOP-DAY', qty: 1 }], 'NET30');
  const fee = lateFee(inv, '2026-11-10');
  const due = 57000;
  const daysOverdue = 4;
  const expectedFee = Math.round(due * 0.0004 * daysOverdue);
  assert.equal(fee, expectedFee);
});

